const event=$('Verify event').first().json.event;const map=function externalTaskUpdate(event    ,job    ) {
  if(!event||typeof event.id!=='string'||!/^evt_[a-f0-9]{64}$/.test(event.id)||!Number.isSafeInteger(event.sequence)||event.sequence<1
    ||typeof event.projectId!=='string'||!job||typeof job.id!=='string'||!/^job_[a-f0-9]{64}$/.test(job.id)
    ||typeof job.workflowReference!=='string'||! /^[a-zA-Z0-9:_-]{1,200}$/.test(job.workflowReference)
    ||typeof event.agreementDigest!=='string'||! /^[a-f0-9]{64}$/.test(event.agreementDigest)||job.current?.agreementDigest!==event.agreementDigest
    ||job.current?.projectId!==event.projectId||typeof job.current?.headEventHash!=='string'
    ||!/^sha256:[a-f0-9]{64}$/.test(job.current.headEventHash))throw new Error('EXTERNAL_TASK_CORRELATION_INVALID');
  const c=job.continuation;
  if(!c||c.schema!=='prooftask.automation-continuation/v1'||typeof c.nextAction!=='string')throw new Error('EXTERNAL_TASK_READBACK_REQUIRED');
  // Do not let an old notification or an inconsistent projection upgrade the current facts.
  const accepted=job.submitted===true&&job.appliesToSavedSubmission===true&&job.decisionForSavedSubmission==='ACCEPT'
    &&job.current.state==='BUYER_CONFIRMED'&&c.acceptedForSavedSubmission===true&&c.nextAction==='RECORD_ACCEPTANCE';
  if((c.acceptedForSavedSubmission===true||c.nextAction==='RECORD_ACCEPTANCE')&&!accepted)throw new Error('EXTERNAL_TASK_DECISION_CONFLICT');
  return {...job,eventId:event.id,eventSequence:event.sequence,id:job.id,jobId:job.id,workflowReference:job.workflowReference,
    deduplicationKey:event.id+':'+job.id,projectId:event.projectId,observedHeadEventHash:job.current.headEventHash,
    observedAt:job.current.observedAt,currentState:job.current.state,nextAction:c.nextAction,acceptedForSavedSubmission:accepted,
    paymentVerified:false,recordVerified:false,signatureVerified:false,
    receiverAction:'UPSERT_ORIGINAL_TASK',notice:'Persist by workflowReference/job ID with event deduplication and current readback. This mapping performs no external write and proves no downstream completion.'};
};return $input.all().map(i=>({json:map(event,i.json)}));
